package hr

import (
	"context"
	"github.com/jmoiron/sqlx"
	"myapp/models"
)

type ReviewStore struct {
	DB *sqlx.DB
}

func (s *ReviewStore) GetPerformanceReview(ctx context.Context, reviewID string) (*models.PerformanceReview, error) {
	var rev models.PerformanceReview

	// BOLA: Fetches sensitive employee performance review without employee or manager scoping.
	query := `SELECT id, employee_id, reviewer_id, rating, confidential_feedback FROM performance_reviews WHERE id = $1`
	if err := s.DB.GetContext(ctx, &rev, query, reviewID); err != nil {
		return nil, err
	}

	return &rev, nil
}

corrected_code:
package hr

import (
	"context"
	"github.com/jmoiron/sqlx"
	"myapp/auth"
	"myapp/models"
)

type ReviewStore struct {
	DB *sqlx.DB
}

func (s *ReviewStore) GetPerformanceReview(ctx context.Context, reviewID string) (*models.PerformanceReview, error) {
	var rev models.PerformanceReview
	currentEmpID := auth.CurrentEmployeeID(ctx)

	query := `SELECT id, employee_id, reviewer_id, rating, confidential_feedback FROM performance_reviews WHERE id = $1 AND (employee_id = $2 OR reviewer_id = $2)`
	if err := s.DB.GetContext(ctx, &rev, query, reviewID, currentEmpID); err != nil {
		return nil, err
	}

	return &rev, nil
}
